//! Request/response examples from Elastic's OpenAPI specs, shown when a Console preset is picked.
//!
//! `assets/api_examples.json` is generated by `scripts/gen_api_examples.py` and keyed by
//! `"METHOD /preset/path"` (the preset path without its query string). Example request
//! bodies go into the body editor under `####### EXAMPLE n: … #######` marker lines; a
//! request still containing a marker is held back by [`render_examples_prompt`].

use std::collections::HashMap;
use std::sync::OnceLock;

use egui::Ui;
use serde::Deserialize;

use crate::ui::theme::Theme;

/// Every example header line starts with this, in both the body and the response box.
pub const EXAMPLE_MARKER: &str = "####### EXAMPLE";
const MARKER_TAIL: &str = " #######";

const DATA: &str = include_str!("../../assets/api_examples.json");

#[derive(Debug, Deserialize)]
pub struct Example {
    pub summary: String,
    pub value: String,
}

#[derive(Debug, Default, Deserialize)]
pub struct OperationExamples {
    /// The operation's page in Elastic's online API reference.
    #[serde(default)]
    pub doc_url: Option<String>,
    #[serde(default)]
    pub request: Vec<Example>,
    #[serde(default)]
    pub response: Vec<Example>,
}

fn table() -> &'static HashMap<String, OperationExamples> {
    static TABLE: OnceLock<HashMap<String, OperationExamples>> = OnceLock::new();
    TABLE.get_or_init(|| serde_json::from_str(DATA).unwrap_or_default())
}

/// Examples for a preset, matched on method and path (query string ignored).
pub fn lookup(method: &str, path: &str) -> Option<&'static OperationExamples> {
    let path = path.split('?').next().unwrap_or(path);
    table().get(&format!("{} {}", method, path))
}

fn header(label: &str, summary: &str) -> String {
    format!("{}{}: {}{}", EXAMPLE_MARKER, label, summary, MARKER_TAIL)
}

/// Summary on the `EXAMPLE 0` block, which holds the preset's own hand-written body.
pub const PRESET_EXAMPLE_SUMMARY: &str = "Drastic Smurf preset";

/// Body editor text for a preset. Every block is marked: the preset's own body is
/// `EXAMPLE 0` and the documented request examples follow as `EXAMPLE 1..n`.
/// When the docs have no request examples the preset body is returned unmarked, so
/// presets without examples still send in one click.
pub fn request_text(method: &str, path: &str, preset_body: Option<&str>) -> String {
    let preset_body = preset_body.unwrap_or_default().trim_end();
    let examples = lookup(method, path)
        .map(|e| e.request.as_slice())
        .unwrap_or(&[]);
    if examples.is_empty() {
        return preset_body.to_string();
    }
    let mut text = String::new();
    if !preset_body.is_empty() {
        text.push_str(&header(" 0", PRESET_EXAMPLE_SUMMARY));
        text.push('\n');
        text.push_str(preset_body);
    }
    for (i, example) in examples.iter().enumerate() {
        if !text.is_empty() {
            text.push_str("\n\n");
        }
        text.push_str(&header(&format!(" {}", i + 1), &example.summary));
        text.push('\n');
        text.push_str(example.value.trim_end());
    }
    text
}

/// Response box text for a preset: each documented response example under a marker
/// line, or `None` when the docs have none.
pub fn response_text(method: &str, path: &str) -> Option<String> {
    let examples = &lookup(method, path)?.response;
    if examples.is_empty() {
        return None;
    }
    let blocks: Vec<String> = examples
        .iter()
        .map(|e| {
            format!(
                "{}\n{}",
                header(" RESPONSE", &e.summary),
                e.value.trim_end()
            )
        })
        .collect();
    Some(blocks.join("\n\n"))
}

fn is_marker(line: &str) -> bool {
    line.trim_start().starts_with(EXAMPLE_MARKER)
}

/// Number of example marker lines in `text`.
pub fn count_examples(text: &str) -> usize {
    text.lines().filter(|l| is_marker(l)).count()
}

pub fn has_examples(text: &str) -> bool {
    text.lines().any(is_marker)
}

/// The marked blocks in `text`: (header line, content below it up to the next marker).
pub fn example_blocks(text: &str) -> Vec<(String, String)> {
    let mut blocks: Vec<(String, String)> = Vec::new();
    for line in text.split_inclusive('\n') {
        if is_marker(line) {
            blocks.push((line.trim().to_string(), String::new()));
        } else if let Some((_, content)) = blocks.last_mut() {
            content.push_str(line);
        }
    }
    for (_, content) in &mut blocks {
        *content = content.trim().to_string();
    }
    blocks
}

/// Short label for a block's header line, e.g. "1: Create an index."
fn block_label(header: &str) -> String {
    header
        .trim_start_matches(EXAMPLE_MARKER)
        .trim_end_matches(MARKER_TAIL.trim())
        .trim()
        .to_string()
}

/// Keep only the content of block `index` (marker removed), dropping everything else.
pub fn keep_only(text: &str, index: usize) -> Option<String> {
    example_blocks(text)
        .into_iter()
        .nth(index)
        .map(|(_, content)| content)
}

/// Drop every example block. Examples sit after any text the user typed above them,
/// so everything from the first marker line onwards goes.
pub fn remove_example_blocks(text: &str) -> String {
    let mut kept = String::new();
    for line in text.split_inclusive('\n') {
        if is_marker(line) {
            break;
        }
        kept.push_str(line);
    }
    kept.trim_end().to_string()
}

/// Keep the example text but delete the marker lines, for when an example was edited
/// in place and is now the intended body.
pub fn strip_markers(text: &str) -> String {
    let kept: String = text
        .split_inclusive('\n')
        .filter(|line| !is_marker(line))
        .collect();
    kept.trim().to_string()
}

/// What the user chose in the "body still contains examples" prompt.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PromptChoice {
    /// Example blocks were removed; the caller should send now.
    RemovedAndSend,
    /// Marker lines were removed; the caller should not send (the user reviews first).
    MarkersStripped,
    /// Only one example was kept; the caller should not send (the user reviews first).
    KeptOne,
    Cancelled,
}

/// Modal shown when Send is pressed while the body still contains example markers.
/// Edits `body` according to the choice; returns `None` while the modal stays open.
pub fn render_examples_prompt(ui: &Ui, id: &str, body: &mut String) -> Option<PromptChoice> {
    let count = count_examples(body);
    let mut choice = None;
    let mut use_block: Option<usize> = None;
    let modal = egui::Modal::new(egui::Id::new(id)).show(ui.ctx(), |ui| {
        ui.set_max_width(480.0);
        ui.heading(
            egui::RichText::new("📖 Body still contains API doc examples").color(Theme::warning()),
        );
        ui.add_space(6.0);
        ui.label(format!(
            "The request body has {} example block{} from the API documentation (the `{}` lines). \
             They're there for reference and won't be valid as a request.",
            count,
            if count == 1 { "" } else { "s" },
            EXAMPLE_MARKER
        ));
        ui.add_space(4.0);
        let kept = remove_example_blocks(body);
        ui.label(
            egui::RichText::new(if kept.is_empty() {
                "Removing the examples leaves an empty body.".to_string()
            } else {
                format!(
                    "Removing the examples keeps the {} line(s) above the first example.",
                    kept.lines().count()
                )
            })
            .color(Theme::text_secondary()),
        );
        let blocks = example_blocks(body);
        if !blocks.is_empty() {
            ui.add_space(8.0);
            ui.label(
                egui::RichText::new("Or keep just one example to edit before sending:")
                    .color(Theme::text_secondary()),
            );
            egui::ScrollArea::vertical()
                .max_height(180.0)
                .show(ui, |ui| {
                    for (i, (header, _)) in blocks.iter().enumerate() {
                        ui.horizontal(|ui| {
                            if ui.small_button("Use").clicked() {
                                use_block = Some(i);
                                choice = Some(PromptChoice::KeptOne);
                            }
                            ui.label(
                                egui::RichText::new(block_label(header))
                                    .monospace()
                                    .size(11.0),
                            );
                        });
                    }
                });
        }
        ui.add_space(10.0);
        ui.horizontal(|ui| {
            let accent = Theme::accent();
            if ui
                .add(
                    egui::Button::new(
                        egui::RichText::new("🧹 Remove examples & send")
                            .color(Theme::contrast_text_color(accent)),
                    )
                    .fill(accent),
                )
                .clicked()
            {
                choice = Some(PromptChoice::RemovedAndSend);
            }
            if ui
                .button("Remove marker lines only")
                .on_hover_text(
                    "Keep the example text (e.g. one you edited in place) and just delete the \
                     marker lines, then review before sending",
                )
                .clicked()
            {
                choice = Some(PromptChoice::MarkersStripped);
            }
            if ui.button("Cancel").clicked() {
                choice = Some(PromptChoice::Cancelled);
            }
        });
    });
    if modal.should_close() && choice.is_none() {
        choice = Some(PromptChoice::Cancelled);
    }
    match choice {
        Some(PromptChoice::RemovedAndSend) => *body = remove_example_blocks(body),
        Some(PromptChoice::MarkersStripped) => *body = strip_markers(body),
        Some(PromptChoice::KeptOne) => {
            if let Some(text) = use_block.and_then(|i| keep_only(body, i)) {
                *body = text;
            }
        }
        _ => {}
    }
    choice
}

/// Body toolbar controls. While the body holds example blocks: a "Keep one" menu and
/// "🧹 Remove examples". Once they're gone, "📖 Show examples" puts `available` (the
/// examples last inserted for this request) back below whatever the body now holds.
/// Returns true when the body changed.
pub fn examples_toolbar(ui: &mut Ui, body: &mut String, available: Option<&str>) -> bool {
    if has_examples(body) {
        let mut changed = false;
        let blocks = example_blocks(body);
        ui.menu_button("📌 Keep one ▾", |ui| {
            for (i, (header, _)) in blocks.iter().enumerate() {
                if ui.button(block_label(header)).clicked() {
                    if let Some(text) = keep_only(body, i) {
                        *body = text;
                        changed = true;
                    }
                    ui.close_menu();
                }
            }
        })
        .response
        .on_hover_text("Replace the body with a single example, ready to edit");
        if ui
            .small_button("🧹 Remove examples")
            .on_hover_text("Delete every example block, keeping anything typed above the first one")
            .clicked()
        {
            *body = remove_example_blocks(body);
            changed = true;
        }
        return changed;
    }
    let Some(examples) = available.filter(|e| has_examples(e)) else {
        return false;
    };
    if ui
        .small_button("📖 Show examples")
        .on_hover_text("Insert this request's examples again, below the current body")
        .clicked()
    {
        let current = body.trim_end();
        *body = if current.is_empty() {
            examples.to_string()
        } else {
            format!("{}\n\n{}", current, examples)
        };
        return true;
    }
    false
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn data_parses_and_covers_create_index() {
        assert!(table().len() > 50, "embedded examples failed to parse");
        let create = lookup("PUT", "/{{index}}").expect("create index examples");
        assert!(create.request.len() >= 2);
        assert!(
            lookup("PUT", "/{{index}}?pretty").is_some(),
            "query string ignored"
        );
        assert!(lookup("GET", "/{{index}}").is_none(), "method must match");
        for (key, op) in table() {
            for e in op.request.iter().chain(&op.response) {
                assert!(!e.value.trim().is_empty(), "{} has an empty example", key);
                assert!(!e.summary.contains('\n'), "{} summary spans lines", key);
            }
        }
    }

    #[test]
    fn doc_urls_point_at_operation_pages() {
        let create = lookup("PUT", "/{{index}}").unwrap();
        assert_eq!(
            create.doc_url.as_deref(),
            Some(
                "https://www.elastic.co/docs/api/doc/elasticsearch/operation/operation-indices-create"
            )
        );
        for (key, op) in table() {
            let url = op.doc_url.as_deref().unwrap_or_default();
            assert!(
                url.starts_with("https://www.elastic.co/docs/api/doc/")
                    && url.contains("/operation/operation-")
                    && url == url.to_lowercase(),
                "{} has a bad doc url: {:?}",
                key,
                url
            );
        }
    }

    #[test]
    fn request_text_marks_preset_body_as_example_zero() {
        let text = request_text("PUT", "/{{index}}", Some("{\"settings\": {}}\n"));
        assert!(text.starts_with(
            "####### EXAMPLE 0: Drastic Smurf preset #######\n{\"settings\": {}}\n\n####### EXAMPLE 1: "
        ));
        let n = lookup("PUT", "/{{index}}").unwrap().request.len();
        assert_eq!(count_examples(&text), n + 1);
        assert_eq!(remove_example_blocks(&text), "");
        assert_eq!(keep_only(&text, 0).as_deref(), Some("{\"settings\": {}}"));
        assert!(keep_only(&text, 1).unwrap().starts_with('{'));
        assert!(keep_only(&text, n + 1).is_none());
        let blocks = example_blocks(&text);
        assert_eq!(blocks.len(), n + 1);
        assert_eq!(block_label(&blocks[0].0), "0: Drastic Smurf preset");

        // Text typed above the examples survives removal.
        let typed = format!("{{}}\n{}", text);
        assert_eq!(remove_example_blocks(&typed), "{}");

        // No documented request examples: the preset body stays unmarked.
        let health = request_text("GET", "/_cluster/health", Some("{}"));
        assert_eq!(health, "{}");

        let bare = request_text("PUT", "/{{index}}", None);
        assert!(bare.starts_with(EXAMPLE_MARKER));
        assert_eq!(remove_example_blocks(&bare), "");

        // Unknown operation: just the preset body.
        assert_eq!(request_text("GET", "/nope", Some("{}")), "{}");
        assert!(response_text("GET", "/nope").is_none());
    }

    #[test]
    fn strip_markers_keeps_example_text() {
        let body = "####### EXAMPLE 1: Create #######\n{\n  \"a\": 1\n}\n";
        assert_eq!(strip_markers(body), "{\n  \"a\": 1\n}");
        assert!(!has_examples(&strip_markers(body)));
        assert!(has_examples("  ####### EXAMPLE 2: x #######"));
        assert!(!has_examples("# just a comment\n{}"));
    }

    #[test]
    fn response_text_marks_every_example() {
        let text = response_text("GET", "/_cluster/health").expect("health response example");
        assert!(text.starts_with("####### EXAMPLE RESPONSE: "));
        assert!(has_examples(&text));
    }
}
